//! Test that C++ overloads for [`std::span`][span] can be successfully represented in Rust.
//!
//! [span]: https://en.cppreference.com/cpp/container/span

#![allow(unused_braces, reason = "Generated by overload! macro")]

use cpp::cpp;
use splat_overload::overload;

use std::ffi::{c_char, c_size_t, c_void};
use std::marker::PhantomData;

// C++ header includes
cpp! {{
    #include <span>
    #include <cstddef>
}}

/// Workaround for missing generic support in the `overload!` macro.
pub type T = std::ffi::c_int;

/// A wrapper struct holding a pointer to a C++ `std::span<int>` object.
#[cfg_attr(not(test), expect(dead_code, reason = "Only used in tests"))]
pub struct StdSpan(*mut c_void, PhantomData<T>);

#[cfg_attr(not(test), expect(dead_code, reason = "Only used in tests"))]
#[allow(
    non_upper_case_globals,
    reason = "Triggered by cpp! macro in rust-analyzer"
)]
impl StdSpan {
    /// Create a default-constructed C++ `std::span<int>`.
    fn default() -> StdSpan {
        let span = unsafe {
            cpp!([] -> *mut c_void as "std::span<int>*" {
                return new std::span<int>();
            })
        };

        StdSpan(span, PhantomData)
    }

    fn size(&self) -> c_size_t {
        let span = self.0 as *const c_void;

        unsafe {
            cpp!([span as "const std::span<int>*"] -> c_size_t as "size_t" {
                return span->size();
            })
        }
    }

    fn data_is_null(&self) -> bool {
        let span = self.0 as *const c_void;

        let data_is_null = unsafe {
            cpp!([span as "const std::span<int>*"] -> c_char as "char" {
                // Use `char` because Rust's `bool` isn't safe to receive across the FFI boundary.
                return span->data() == nullptr;
            })
        };

        // Convert the `c_char` result back to a Rust `bool`.
        data_is_null != 0
    }
}

overload! {
    impl StdSpan {
        /// Construct an empty span.
        pub fn new() -> StdSpan {
            StdSpan::default()
        }
    }
}

#[test]
fn test_span() {
    let span = StdSpan::new();

    assert_eq!(span.size(), 0);
    assert!(span.data_is_null());
}
